```python
import random
import time


def linear_search(nums, target):
    for i, x in enumerate(nums):
        if x == target:
            return i
    return -1


def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def compare(n, trials=200):
    nums = list(range(n))
    rng = random.Random(0)
    targets = [rng.randrange(n) for _ in range(trials)]
    start = time.perf_counter()
    for t in targets:
        linear_search(nums, t)
    lin = time.perf_counter() - start
    start = time.perf_counter()
    for t in targets:
        binary_search(nums, t)
    bin_ = time.perf_counter() - start
    return lin, bin_


for n in (1_000, 10_000):
    lin, bin_ = compare(n)
    print(f"n={n:>7,}  linear {lin:.4f}s  binary {bin_:.6f}s")
```

On a laptop you'll see something like linear ≈ 0.004 s, 0.04 s, 0.4 s and binary ≈ 0.0002 s at every size. Linear is O(n): ten times the data, ten times the time. Binary is O(log n): ten times the data adds about 3.3 looks per search.

