import math


def same_line(v, w):
    return math.isclose(v[0] * w[1] - v[1] * w[0], 0.0, abs_tol=1e-12)


def in_span_3d(u, v, t):
    d = u[0] * v[1] - u[1] * v[0]
    a = (t[0] * v[1] - t[1] * v[0]) / d
    b = (u[0] * t[1] - u[1] * t[0]) / d
    return math.isclose(a * u[2] + b * v[2], t[2], abs_tol=1e-9)


